import { describe, expect, it } from 'vitest'
import contractJson from '../../../../../contracts/openapi.json'
import { ADMIN_LIMITS, REQUEST_LIMITS, upToCharacters } from './limits'

interface Property {
  maxLength?: number
}
interface Parameter {
  name: string
  schema: Property
}
interface Contract {
  components: { schemas: Record<string, { properties: Record<string, Property> }> }
  paths: Record<string, { get?: { parameters?: Parameter[] } }>
}

// The executable contract (generated by the backend). If a limit changes there, this test fails
// and limits.ts must be updated in the same change.
const contract = contractJson as unknown as Contract

function maxLength(schema: string, property: string): number | undefined {
  return contract.components.schemas[schema]?.properties[property]?.maxLength
}

describe('REQUEST_LIMITS match contracts/openapi.json', () => {
  it.each([
    ['SubmitPurchaseRequest', 'itemName', REQUEST_LIMITS.itemNameMax],
    ['SubmitPurchaseRequest', 'description', REQUEST_LIMITS.descriptionMax],
    ['SubmitPurchaseRequest', 'justification', REQUEST_LIMITS.justificationMax],
    ['SubmitLeaveRequest', 'reason', REQUEST_LIMITS.leaveReasonMax],
    ['AddCommentRequest', 'body', REQUEST_LIMITS.commentMax],
    ['ApproveTaskRequest', 'comment', REQUEST_LIMITS.approveCommentMax],
    ['RejectTaskRequest', 'reason', REQUEST_LIMITS.rejectReasonMax],
    ['FulfillTaskRequest', 'note', REQUEST_LIMITS.fulfillNoteMax],
  ] as const)('%s.%s max length', (schema, property, limit) => {
    expect(maxLength(schema, property)).toBe(limit)
  })

  it.each([
    ['CreateUserRequest', 'email', ADMIN_LIMITS.emailMax],
    ['CreateUserRequest', 'displayName', ADMIN_LIMITS.displayNameMax],
    ['UpdateUserRequest', 'displayName', ADMIN_LIMITS.displayNameMax],
    ['CreateUserRequest', 'initialPassword', ADMIN_LIMITS.passwordMax],
    ['ResetPasswordRequest', 'newPassword', ADMIN_LIMITS.passwordMax],
    ['CreateDepartmentRequest', 'name', ADMIN_LIMITS.departmentNameMax],
    ['UpdateDepartmentRequest', 'name', ADMIN_LIMITS.departmentNameMax],
    ['CreateDepartmentRequest', 'code', ADMIN_LIMITS.departmentCodeMax],
  ] as const)('admin %s.%s max length', (schema, property, limit) => {
    expect(maxLength(schema, property)).toBe(limit)
  })

  it('password minimum matches the contract', () => {
    const initial = contract.components.schemas['CreateUserRequest']?.properties['initialPassword'] as { minLength?: number } | undefined
    expect(initial?.minLength).toBe(ADMIN_LIMITS.passwordMin)
  })

  it('item name allows 150 characters (not 120)', () => {
    expect(REQUEST_LIMITS.itemNameMax).toBe(150)
  })

  it('search limit matches the GET /api/requests parameter', () => {
    const search = contract.paths['/api/requests']?.get?.parameters?.find((p) => p.name === 'search')
    expect(search?.schema.maxLength).toBe(REQUEST_LIMITS.searchMax)
  })

  it('formats helper text from the number', () => {
    expect(upToCharacters(REQUEST_LIMITS.itemNameMax)).toBe('Up to 150 characters.')
  })
})
